#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example() {
        let e = [(0, 1, 4), (0, 2, 1), (2, 1, 2), (1, 3, 1)];
        assert_eq!(shortest_paths(4, &e, 0), vec![Some(0), Some(3), Some(1), Some(4)]);
        assert_eq!(shortest_path(4, &e, 0, 3), Some((4, vec![0, 2, 1, 3])));
    }

    #[test]
    fn unreachable_and_directed() {
        let e = [(0, 1, 5), (2, 0, 1)];
        assert_eq!(shortest_paths(4, &e, 0), vec![Some(0), Some(5), None, None]);
        assert_eq!(shortest_path(4, &e, 0, 2), None);
        assert_eq!(shortest_path(4, &e, 3, 3), Some((0, vec![3])));
    }

    #[test]
    fn parallel_edges_self_loops_zero_weights() {
        let e = [(0, 1, 10), (0, 1, 3), (1, 1, 0), (1, 2, 0), (0, 2, 7)];
        assert_eq!(shortest_paths(3, &e, 0), vec![Some(0), Some(3), Some(3)]);
    }

    #[test]
    fn path_is_consistent() {
        let e = [(0, 1, 2), (1, 2, 2), (0, 2, 5), (2, 3, 1), (1, 3, 10)];
        let (d, p) = shortest_path(4, &e, 0, 3).unwrap();
        assert_eq!(d, 5);
        assert_eq!(p, vec![0, 1, 2, 3]);
    }

    #[test]
    fn large_grid_is_fast() {
        let w = 200;
        let mut e = vec![];
        for r in 0..w {
            for c in 0..w {
                let v = r * w + c;
                if c + 1 < w { e.push((v, v + 1, 1)); }
                if r + 1 < w { e.push((v, v + w, 1)); }
            }
        }
        let d = shortest_paths(w * w, &e, 0);
        assert_eq!(d[w * w - 1], Some(2 * (w as u64 - 1)));
    }
}
